export const getNormalizedQty = (value: number, isKgOrLitre?: boolean) => {
  if (!Number.isFinite(value) || value <= 0) {
    return isKgOrLitre ? 0.01 : 1;
  }

  if (isKgOrLitre) {
    return Number(value.toFixed(3));
  }

  return Math.max(1, Math.round(value));
};

export const normalizeProductRecords = (value: unknown): IProductData[] => {
  if (!value || typeof value !== 'object') {
    return [];
  }

  const data = value as { records?: unknown };

  return Array.isArray(data.records) ? (data.records as IProductData[]) : [];
};

export const normalizePackageDetails = (
  value: unknown
): IPackageDetailsData | null => {
  if (!value || typeof value !== 'object') {
    return null;
  }

  const data = value as Partial<IPackageDetailsData> & { items?: unknown };
  const items = Array.isArray(data.items)
    ? (data.items as Partial<IPackageItemData>[]).map((item) => ({
        categoryName:
          typeof item.categoryName === 'string' ? item.categoryName : undefined,
        imageUrl: typeof item.imageUrl === 'string' ? item.imageUrl : undefined,
        isKgOrLitre:
          typeof item.isKgOrLitre === 'boolean'
            ? item.isKgOrLitre
            : undefined,
        productCode: String(item.productCode ?? ''),
        productId: String(item.productId ?? ''),
        productName: String(item.productName ?? ''),
        qty: getNormalizedQty(
          Number(item.qty ?? 1),
          item.isKgOrLitre as boolean | undefined
        ),
        unitPrice:
          typeof item.unitPrice === 'number'
            ? item.unitPrice
            : item.unitPrice !== undefined
              ? Number(item.unitPrice)
              : undefined,
      }))
    : [];

  return {
    items,
    packageCode: String(data.packageCode ?? ''),
    packageId: String(data.packageId ?? ''),
    packageName: String(data.packageName ?? ''),
    unitPrice: Number(data.unitPrice ?? 0),
  };
};
